def max_chain_length(pairs, n):
    # Initialize a dictionary to store the maximum length of chains ending at each node
    dp = {i: 1 for i in range(n)}

    # Iterate through each pair in the input list
    for i in range(n):
        for j in range(i + 1, n):
            # Check if the current pair forms a valid chain ending at node i
            if pairs[i].x <= pairs[j].y:
                # Update the maximum length of chain ending at node i
                dp[i] = max(dp[i], dp[j] + 1)

    # Find the maximum value in the dictionary, which represents the longest chain
    return max(dp.values())

